  --ink: #ece8dd;
  --muted: #a99f8f;
  --faint: #7c7364;
  --accent: #ece8dd;
  --accent-fg: #1c1b17;
  --clay: #e08a63;
  --clay-soft: #38241c;
  --clay-soft-text: #f0b595;
  --ring: rgba(236, 232, 221, 0.14);
  --shadow-card: 0 1px 2px rgba(0, 0, 0, 0.35), 0 12px 32px rgba(0, 0, 0, 0.35);
}

@theme {
  --font-sans: "SF Pro Text", "SF Pro Display", "Geist", "Helvetica Neue", system-ui, -apple-system, sans-serif;
  --font-serif: "Newsreader", "Instrument Serif", "Playfair Display", Georgia, "Times New Roman", serif;
  --font-mono: "Geist Mono", "SF Mono", "JetBrains Mono", ui-monospace, "SFMono-Regular", monospace;

  --color-canvas: var(--canvas);
  --color-card: var(--card);
  --color-subtle: var(--subtle);
  --color-line: var(--line);
  --color-ink: var(--ink);
  --color-muted: var(--muted);
  --color-faint: var(--faint);
  --color-accent: var(--accent);
  --color-accent-fg: var(--accent-fg);
  --color-clay: var(--clay);
  --color-clay-soft: var(--clay-soft);
  --color-clay-soft-text: var(--clay-soft-text);
  --color-ring: var(--ring);

  --shadow-card: var(--shadow-card);
}

html,
body,
#root {
  height: 100%;
}

html {
  scroll-behavior: smooth;
}

body {
  background: var(--canvas);
  color: var(--ink);
  font-family: var(--font-sans);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
  overscroll-behavior-y: none;
}

::selection {
  background: var(--clay-soft);
  color: var(--clay-soft-text);
}

:focus-visible {
  outline: 2px solid var(--clay);
  outline-offset: 2px;
  border-radius: 6px;
}

/* ---------- Motion ---------- */
@media (prefers-reduced-motion: no-preference) {
  @keyframes rise {
    from {
      opacity: 0;
      transform: translateY(14px);
    }
    to {
      opacity: 1;
      transform: translateY(0);
    }
  }

  @keyframes pop {
    0% {
      transform: scale(0.6);
    }
    60% {
      transform: scale(1.18);
    }
    100% {
      transform: scale(1);
    }
  }

  @keyframes barGrow {
    from {
      transform: scaleX(0);
    }
    to {
      transform: scaleX(1);
    }
  }

  @keyframes fadeIn {
    from {
      opacity: 0;
    }
    to {
      opacity: 1;
    }
  }

  .screen-enter {
    animation: rise 0.5s cubic-bezier(0.16, 1, 0.3, 1) both;
  }

  .screen-enter > * {
    animation: rise 0.55s cubic-bezier(0.16, 1, 0.3, 1) both;
    animation-delay: calc(var(--i, 0) * 70ms);
  }

  .check-pop {
    animation: pop 0.38s cubic-bezier(0.34, 1.56, 0.64, 1);
  }

  .progress-fill {
    transform-origin: left;
    animation: barGrow 0.6s cubic-bezier(0.16, 1, 0.3, 1) both;
  }

  .fade-in {
    animation: fadeIn 0.35s ease both;
  }

  .surface-lift {
    transition: box-shadow 200ms ease, transform 200ms ease;
  }

  .surface-lift:hover {
    box-shadow: var(--shadow-card);
  }

  button:active {
    transform: scale(0.97);
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

/* Respect reduced motion for smooth scroll */
@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }
}

/* ---------- Details ---------- */
.no-scrollbar::-webkit-scrollbar {
  display: none;
}

.no-scrollbar {
  -ms-overflow-style: none;
  scrollbar-width: none;
}

