    swatch: '#c2912f',
    light: { bg: '#f6eed3', text: '#7a5b14', solid: '#c2912f' },
    dark: { bg: '#342b15', text: '#eed08a', solid: '#e0b45a' }
  },
  dusty: {
    label: 'Blaugrau',
    swatch: '#3f6e93',
    light: { bg: '#e1eaf0', text: '#2c4e6b', solid: '#3f6e93' },
    dark: { bg: '#1f2b37', text: '#a9c4dc', solid: '#74a6c9' }
  },
  plum: {
