        <section aria-label="Gewohnheiten" style={{ '--i': 2 } as React.CSSProperties}>
          <div className="flex items-center justify-between">
            <SectionLabel>Heute · {total} {total === 1 ? 'Gewohnheit' : 'Gewohnheiten'}</SectionLabel>
            <button
