      a.href = url;
      a.download = `rhythm-export-${new Date().toLocaleDateString('de-DE').replace(/\./g, '-')}.json`;
      document.body.appendChild(a);
      a.click();
      a.remove();
      URL.revokeObjectURL(url);
      setExported(true);
      window.setTimeout(() => setExported(false), 2500);
    } catch {
      setExported(false);
    }
  };

